from __future__ import annotations

from typing import Any

import pytest

from llm_router import Model, Provider
from llm_router._api.types import ProviderCredential
import llm_router._internal.runtime.executor as runtime_executor
from llm_router._internal.runtime.errors import AttemptLeftError
from llm_router._internal.runtime.output import ProviderResult
from llm_router._internal.runtime.requests import ProviderRequest

pytestmark = pytest.mark.verification_kind("unit")


class DummyEvent:
    def __init__(self, is_set_val: bool) -> None:
        self.is_set_val = is_set_val

    def is_set(self) -> bool:
        return self.is_set_val


class DummyAdapter:
    def __init__(self) -> None:
        self.called = False

    @property
    def capabilities(self) -> Any:
        return None

    def execute(self, request: ProviderRequest) -> ProviderResult:
        self.called = True
        return ProviderResult(
            data={"req": request.request_id},
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            provider_model="test-model",
            output_text="test",
        )

    async def aexecute(self, request: ProviderRequest) -> ProviderResult:
        self.called = True
        return ProviderResult(
            data={"req": request.request_id},
            provider=Provider.OPENROUTER,
            model=Model.DEEPSEEK_V3,
            provider_model="test-model",
            output_text="test",
        )


@pytest.mark.verifies("TREQ_TIMED_OUT_ATTEMPT_STOPS[revision==1]")
def test_timed_out_left_attempt_stops_further_provider_request_sync() -> None:
    adapter_class = next(
        iter(
            [
                cls
                for name, cls in vars(runtime_executor).items()
                if type(cls) is type and name.endswith("LeftAttemptAdapter")
            ]
        )
    )
    underlying = DummyAdapter()
    flag = DummyEvent(is_set_val=True)
    wrapped = adapter_class(underlying, flag)

    request = ProviderRequest(
        request_id="req-1",
        provider=Provider.OPENROUTER,
        model=Model.DEEPSEEK_V3,
        provider_model="test-model",
        credential=ProviderCredential(key_id=1, env_var="VAR", value="val"),
        messages=(),
    )

    with pytest.raises(AttemptLeftError, match=r""):
        wrapped.execute(request)

    assert not underlying.called


